#!/usr/bin/env python3
"""JSON entry point for the controller project."""
import sys
sys.path.insert(0, '/workspace/vendor')
import json
import os

if '/workspace/native' not in os.environ.get('LD_LIBRARY_PATH', ''):
    # Defensive: the bundled native runtime libraries must be resolvable even
    # when the environment does not advertise them.
    import ctypes
    for _name in ('libz.so.1', 'libgcc_s.so.1', 'libstdc++.so.6'):
        _path = os.path.join('/workspace/native', _name)
        if os.path.exists(_path):
            try:
                ctypes.CDLL(_path, mode=ctypes.RTLD_GLOBAL)
            except OSError:
                pass

from controller import run


def main():
    raw = sys.stdin.buffer.read(64 * 1024 * 1024)
    result = run(raw)
    out = sys.stdout
    out.write(json.dumps(result, separators=(',', ':')))
    out.write('\n')
    out.flush()
    sys.exit(0)


if __name__ == '__main__':
    main()
"""Extend the CPU controller with certified epoch planning.

The classifier modules, probability compiler, data loader and metric routines
are the supplied CPU primitives. This module wires strict request validation,
window classification, compiled gates, joint export planning and both
certificates into the published version3 response. See ../PROTOCOL.md.
"""
import sys

# Deep request nesting must fail as invalid instead of exhausting the C stack,
# while the planner's own recursion stays far below this bound.
if sys.getrecursionlimit() > 5000:
    sys.setrecursionlimit(5000)

import metrics
import planner
import probability
from validator import Invalid, parse, validate

_INVALID = {'error': 'invalid'}
_MODELS = {}


def _evaluator(name):
    module = _MODELS.get(name)
    if module is None:
        if name == 'cnn':
            import testcnnonnx as module
        else:
            import testrnnonnx as module
        _MODELS[name] = module
    return module


def classify(name, windows):
    if not windows:
        return []
    sequences = [window[7] for window in windows]
    labels = [0] * len(windows)
    predicts = _evaluator(name).evaluate_model_single_pass(sequences, labels)
    return [int(item) for item in predicts]


def solve(case):
    windows = case['windows']
    predictions = classify(case['model'], windows)
    thresholds = probability.window_thresholds(case['stats'], windows)
    thresholds = [int(item) for item in thresholds]
    model = planner.Model(case, predictions, thresholds)
    plan = planner.plan(model)
    assignment = plan['assignment']
    return {
        'predictions': predictions,
        'reports': metrics.selected_report(case['flows'], windows, predictions,
                                           assignment),
        'ratio': plan['ratio'],
        'thresholds': thresholds,
        'assignment': assignment,
        'utility': plan['utility'],
        'age': plan['age'],
        'flow': plan['flow'],
        'potential': plan['potential'],
        'cut': plan['cut'],
    }


def run(raw):
    try:
        cases = validate(parse(raw))
        results = [solve(case) for case in cases]
    except Invalid:
        return dict(_INVALID)
    except Exception:
        # Any unexpected internal condition still owes the harness a clean
        # zero-exit JSON document; nothing partial may be emitted.
        import os
        if os.environ.get('FENIX_DEBUG'):
            raise
        return dict(_INVALID)
    return {'version': 3, 'results': results}
