class Invalid(Exception):
    """Raised for every rejected request."""


def _pairs(items):
    out = {}
    for key, value in items:
        if key in out:
            raise Invalid('duplicate key')
        out[key] = value
    return out


def _no_float(text):
    raise Invalid('non integer number')


def _no_constant(text):
    raise Invalid('nonfinite number')


def parse(raw):
    if raw is None:
        raise Invalid('no input')
    if len(raw) > MAX_BYTES:
        raise Invalid('oversized')
    try:
        text = raw.decode('utf-8')
    except UnicodeDecodeError:
        raise Invalid('bad utf-8')
    try:
        return json.loads(text, object_pairs_hook=_pairs, parse_float=_no_float,
                          parse_constant=_no_constant)
    except Invalid:
        raise
    except RecursionError:
        raise Invalid('too deep')
    except ValueError:
        raise Invalid('bad json')


